package com.onebytelabs.zlplay;

import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.hardware.Camera;import android.view.*;import android.widget.*;
import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Local camera-only QR reader. Frames are never stored or uploaded. */
@SuppressWarnings("deprecation")
public final class QrScanActivity extends Activity implements SurfaceHolder.Callback {
 private Camera camera;private SurfaceView preview;private TextView help;private boolean visible;private volatile boolean found;private int previewRotation;private int cameraId,lastRotation=Surface.ROTATION_0;private OrientationEventListener orientation;private android.hardware.display.DisplayManager displays;private final android.hardware.display.DisplayManager.DisplayListener displayListener=new android.hardware.display.DisplayManager.DisplayListener(){public void onDisplayAdded(int id){}public void onDisplayRemoved(int id){}public void onDisplayChanged(int id){if(camera!=null)updateOrientation();}};private final AtomicBoolean decoding=new AtomicBoolean();private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.setBackgroundColor(0xff0b121d);preview=new SurfaceView(this);preview.getHolder().addCallback(this);root.addView(preview,new android.widget.FrameLayout.LayoutParams(-1,-1));help=new TextView(this);help.setText(R.string.remote_camera);help.setTextColor(0xffffffff);help.setTextSize(18);help.setPadding(24,16,24,16);help.setBackgroundColor(0xb0000000);root.addView(help,new android.widget.FrameLayout.LayoutParams(-1,-2,Gravity.TOP));Button cancel=new Button(this);cancel.setText(android.R.string.cancel);cancel.setOnClickListener(v->finish());root.addView(cancel,new android.widget.FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.END));setContentView(root);displays=(android.hardware.display.DisplayManager)getSystemService(DISPLAY_SERVICE);displays.registerDisplayListener(displayListener,new Handler(Looper.getMainLooper()));orientation=new OrientationEventListener(this){public void onOrientationChanged(int angle){if(camera!=null&&lastRotation!=getWindowManager().getDefaultDisplay().getRotation())updateOrientation();}};if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.CAMERA},7);}
 public void surfaceCreated(SurfaceHolder holder){visible=true;open();}public void surfaceChanged(SurfaceHolder holder,int f,int w,int h){}public void surfaceDestroyed(SurfaceHolder holder){visible=false;release();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==7&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)open();else help.setText(R.string.remote_camera_denied);}
 private void open(){if(!visible||camera!=null||found||checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;try{Camera.CameraInfo info=new Camera.CameraInfo();cameraId=0;for(int i=0;i<Camera.getNumberOfCameras();i++){Camera.getCameraInfo(i,info);if(info.facing==Camera.CameraInfo.CAMERA_FACING_BACK){cameraId=i;break;}}camera=Camera.open(cameraId);updateOrientation();Camera.Parameters parameters=camera.getParameters();List<Camera.Size> sizes=parameters.getSupportedPreviewSizes();Camera.Size chosen=sizes.get(0);for(Camera.Size size:sizes)if(size.width<=1280&&size.width>=640){chosen=size;break;}parameters.setPreviewSize(chosen.width,chosen.height);parameters.setPreviewFormat(android.graphics.ImageFormat.NV21);if(parameters.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))parameters.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(parameters);camera.setPreviewDisplay(preview.getHolder());camera.setPreviewCallback((frame,source)->{if(found||!decoding.compareAndSet(false,true))return;Camera.Size size=source.getParameters().getPreviewSize();byte[] copy=frame.clone();worker.execute(()->decode(copy,size.width,size.height));});camera.startPreview();}catch(Exception e){release();help.setText(R.string.remote_camera_denied);}}
 private void updateOrientation(){Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(cameraId,info);lastRotation=getWindowManager().getDefaultDisplay().getRotation();int degrees=lastRotation==Surface.ROTATION_90?90:lastRotation==Surface.ROTATION_180?180:lastRotation==Surface.ROTATION_270?270:0;int corrected=info.facing==Camera.CameraInfo.CAMERA_FACING_FRONT?(360-(info.orientation+degrees)%360)%360:(info.orientation-degrees+360)%360;try{camera.setDisplayOrientation(corrected);previewRotation=corrected;}catch(RuntimeException ignored){}}
 private void decode(byte[] data,int width,int height){try{MultiFormatReader reader=new MultiFormatReader();Map<DecodeHintType,Object> hints=new EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.POSSIBLE_FORMATS,Collections.singletonList(BarcodeFormat.QR_CODE));hints.put(DecodeHintType.TRY_HARDER,Boolean.TRUE);Result result=reader.decode(new BinaryBitmap(new HybridBinarizer(new PlanarYUVLuminanceSource(data,width,height,0,0,width,height,false))),hints);String text=result.getText();if(text.startsWith("zlplay-remote:")){found=true;runOnUiThread(()->{setResult(RESULT_OK,new Intent().putExtra("invitation",text));finish();});}}catch(Exception ignored){}finally{decoding.set(false);}}
 private void release(){if(camera!=null){camera.setPreviewCallback(null);camera.stopPreview();camera.release();camera=null;}}
 @Override protected void onPause(){if(orientation!=null)orientation.disable();release();super.onPause();}@Override protected void onResume(){super.onResume();if(orientation!=null)orientation.enable();if(visible)open();}@Override protected void onDestroy(){release();if(displays!=null)displays.unregisterDisplayListener(displayListener);worker.shutdownNow();super.onDestroy();}
}
